// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g, uint256 jump) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(0));
        jump = bound(jump, 2, 1000);

        // lock in a guess
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);

        uint256 lockedBlock = block.number + 1;
        // advance past the locked block so settle is admissible
        vm.roll(lockedBlock + jump);

        // first settle succeeds for every admissible actor (guess rarely matches,
        // and even if it matches the 2-ether transfer is not required for success path)
        vm.prank(actor);
        bool ok1;
        try c.settle() { ok1 = true; } catch { ok1 = false; }

        // second settle must revert: reference reset the block to 0
        vm.prank(actor);
        bool ok2;
        try c.settle() { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok1 && !ok2);
    }
}
